S["CHOOSE_GLYPHS_HELP"] = "在满级之后，你将可以选择3个大型雕文和3个小型雕文。大型雕文可以改变你的一些法术或技能的功能，而小型雕文可以提供美化或小增益效果。\n\n你必须先获得一个雕文后才能选择它。雕文由拥有铭文专业技能的玩家生产。你可以通过与其他玩家交易或者拜访拍卖行来获取雕文。\n\n你可以在技能训练师处重置你的所有雕文，或使用名为%s的物品来切换特定的雕文。";
