S["CHOOSE_SPECIALIZATION"] = "选择你的专精";
S["CHOOSE_SPECIALIZATION_HELP"] = "你的角色现在可以选择一项天赋专精。天赋专精在10级时可提供新的技能，并在更高等级时提供额外的技能。同职业的不同专精大都使用不同的攻击或法术技能。\n\n有些天赋专精可以让你充当不同的作战角色，例如坦克或治疗。你可以随时在职业训练师出变更你的天赋专精。";
