S["CHOOSE_TALENTS"] = "选择你的天赋";
S["CHOOSE_TALENTS_HELP"] = "天赋属于特殊技能，其中部分为主动攻击或法术技能，可以被放入你的动作条中使用；另一部分则为被动技能。\n\n理论上说，天赋选择不存在对错之分。你可以依据自己的兴趣或者游戏风格来选择天赋。每次选择天赋时，你都可以在三个选项中选择一项。\n\n你可以在职业训练师处重置你的所有天赋，或使用名为%s的物品重置某一行的天赋。";
