S["CHOOSE_THE_ALLIANCE"] = "荣誉、信仰、正义、牺牲、传承，这些共同信念促使高贵的联盟种族紧密团结在一起。\n\n无数成员将他们的科学技术、魔法奥秘和精神智慧贡献给了联盟，旨在建立一个和平公正的世界。\n\n扛起这面战旗意味着你将肩负他们的理想，在艾泽拉斯世界中贯彻联盟的信念。";
