S["NEWBIE_TOOLTIP_HELP"] = "你可以通过这个菜单给我们发送建议和报告错误。如果你有什么问题或者需要帮助的话，你还可以使用帮助请求菜单来与我们的GM在游戏中对话。";
S["NEWBIE_TOOLTIP_HONORABLE_KILLS"] = "每当你或你所在的队伍在PvP中对一个敌方玩家造成伤害，并且该玩家随后被杀死，则你可以获得一次荣誉消灭。只有在目标等级对你来说是绿色或更高（即杀死与该玩家等级相当的怪物可以获得经验值）的情况下才能获得荣誉消灭。只有敌方玩家会提供荣誉消灭。";
S["NEWBIE_TOOLTIP_HONOR_CONTRIBUTION_POINTS"] = "荣誉点数是通过在PvP战斗中进行荣誉消灭获得的。杀死敌人可以获得多少点数取决于你（或你所在的队伍）对其造成了多少伤害，并由你所在的小队或团队均分。如果你在短时间内反复杀死同一个敌方玩家，则每次杀死他所获得的荣誉点数也会越来越少，因此，在数次杀死同一个敌方玩家之后，你将获得极少的荣誉点数，甚至不再获得任何荣誉点数。";
S["NEWBIE_TOOLTIP_HONOR_STANDING"] = "排名是根据你与其他同阵营玩家（联盟或部落）的对比得出的。如果你的排名是150，那就是说有149名玩家在上一阶段中获得的荣誉点数比你多。你每周必须获得至少15个荣誉消灭点数才能参与军阶评定。";
S["NEWBIE_TOOLTIP_HORDE"] = "一名部落的成员，和联盟的成员相敌对（暗夜精灵，矮人，人类，侏儒，德莱尼）。";
S["NEWBIE_TOOLTIP_IGNOREPLAYER"] = "将一个玩家添加到你的屏蔽名单中。你将不会收到屏蔽名单上玩家的信息或者别的文字，被屏蔽的玩家也无法使用任何方式与你联络。";
S["NEWBIE_TOOLTIP_IGNORETAB"] = "编辑你想要屏蔽的玩家的名单。";
S["NEWBIE_TOOLTIP_LATENCY"] = "和游戏服务器通讯的平均时间。如果延迟一直很高（红色）的话，那么你的互联网连接可能有问题。";
S["NEWBIE_TOOLTIP_LFGPARENT"] = "这个工具可以帮助你找到并加入一支队伍，或者找到额外的队员来组成你新建立的或已经存在的队伍。";
S["NEWBIE_TOOLTIP_LFG_LIST_EDIT"] = "编辑你当前的队伍列表。";
S["NEWBIE_TOOLTIP_LFMTAB"] = "点击这里以寻找可以加入你的队伍的玩家。";
S["NEWBIE_TOOLTIP_LOOKINGFORGUILDTAB"] = "让您找到一个公会。";
S["NEWBIE_TOOLTIP_MAINMENU"] = "你可以在这里修改你的视频、音频和界面设置，或者自定义快捷键。你还可以在这里选择返回角色选择画面或者退出游戏。";
S["NEWBIE_TOOLTIP_MANABAR0"] = "你现在所拥有的法力值。玩家需要法力值来施放法术。如果你不进行施法动作的时间超过5秒，法力值就会开始自动回复。";
S["NEWBIE_TOOLTIP_MANABAR1"] = "战士（以及德鲁伊的熊形态和巨熊形态）使用技能需要怒气。怒气可以通过制造伤害或者承受伤害获得。";
S["NEWBIE_TOOLTIP_MANABAR2"] = "已废弃";
S["NEWBIE_TOOLTIP_MANABAR3"] = "潜行者（以及德鲁伊的猎豹形态）需要能量来使用他们的技能。能量会不断地自动恢复。";
S["NEWBIE_TOOLTIP_MANABAR4"] = "你现在宠物的喜悦程度。让你的宠物感到满足会让它对敌人造成普通伤害，而高兴状态下的宠物会制造更多的伤害，而不高兴状态下的宠物制造的伤害会减少。当你的宠物死亡或者饥饿状态的时候会降低喜悦程度，而喂食你的宠物能增加它的喜悦程度。";
S["NEWBIE_TOOLTIP_MEMORY"] = "你的插件所占用的内存。你可以通过角色选择画面进入插件管理页面。";
S["NEWBIE_TOOLTIP_MINIMAPTOGGLE"] = "开启/关闭小地图显示";
S["NEWBIE_TOOLTIP_MOUNTS_AND_PETS"] = "查看你所拥有的所有坐骑和宠物。如果你是一位宠物训练师，还可以在此管理你宠物的技能。";
S["NEWBIE_TOOLTIP_MUTEPLAYER"] = "将一个玩家添加到你的禁声列表。你将无法听到禁声列表中的玩家讲话。";
S["NEWBIE_TOOLTIP_PARTYOPTIONS"] = "如果你在一个小队中，你可以右键点击你的头像来打开小队选项菜单。这个菜单可以让你退出队伍或者查看现在使用的物品捡拾方式。小队的领袖可以增加或者移除队员，并且还可以改变物品捡拾方式。";
S["NEWBIE_TOOLTIP_PLAYEROPTIONS"] = "右键点击可以实施和别的玩家交互的特殊命令。你可以查看他们的装备，发出组队邀请，开启交易窗口或者和他进行对决。一个队伍的领导可以提升队伍中队员的作用或者将其移除队伍。";
S["NEWBIE_TOOLTIP_PROMOTE"] = "提升所选择玩家在公会中的会阶。";
S["NEWBIE_TOOLTIP_PROTOCOLS"] = "游戏连接服务器使用的互联网协议版本。IPv6是最新的技术，但因还未受到广泛兼容而可能会导致问题。";
S["NEWBIE_TOOLTIP_PVP"] = "浏览你的荣誉和竞技场战队信息。";
