S["NEWBIE_TOOLTIP_RAIDTAB"] = "查看或者编辑你的大型团队。团队是一支由超过5个玩家组成的队伍，可以用来击败高等级的非常强大的敌人。";
S["NEWBIE_TOOLTIP_RAID_BROWSER"] = "允许你查看其他想要进行特定活动的玩家列表。同时允许你控制是否要让自己出现在该列表上。";
S["NEWBIE_TOOLTIP_RAID_FINDER"] = "这个工具可以帮助你找到一个团队以完成团队副本的战斗。";
S["NEWBIE_TOOLTIP_RANK"] = "荣誉系统的计算结果将以军阶的形式表现。根据你的本周排名和当前军阶级别的对比，你的军阶级别可能会提高、降低或保持不变。高级的玩家提升军阶的速度更快（下降也更慢）。另外，低级军阶提升的速度比高级军阶提升的速度更快。";
S["NEWBIE_TOOLTIP_RANK_POSITION"] = "你在排名体系中的位置。它会告诉你距离晋级或降级还有多远，但是只在每周更新排名时才会随之更新。";
