S["NEWBIE_TOOLTIP_SOCIAL"] = "关于游戏中的其他玩家人物的信息。你可以使用社交窗口来设置你的好友名单和屏蔽名单，以及查看有哪些玩家在线。";
S["NEWBIE_TOOLTIP_SPELLBOOK"] = "你的所有法术和技能。如果你想要将法术或技能图标拖到动作条上，就打开法术和技能窗口，左键点击你想要拖拉的法术或者技能，然后将其拖到动作条上。";
