S["RACE_INFO_BLOODELF"] = "        很久以前，被流放的高等精灵建立了奎尔萨拉斯王国，并制造了一座被称为太阳之井的魔法喷泉。虽然精灵们从太阳之井获得了强大的力量，但他们也变得日益依赖它。许多年后，天灾军团摧毁了太阳之井，杀死了大部分高等精灵。现在，幸存者们开始称自己为血精灵，并努力重建奎尔萨拉斯，同时寻找着新的魔法源泉，以满足他们对于魔法的渴望。";
S["RACE_INFO_BLOODELF_FEMALE"] = "很久以前，高贵的高等精灵围绕着名为太阳之井的魔法喷泉建立起了黄金之城奎尔萨拉斯。但在第三次大战中，巫妖王摧毁了他们的都城，幸存者们只得向部落求助。\n\n这些如今自称为血精灵的流亡者已经是这个灿烂文明的最后遗孑。他们一直致力于重建奎尔萨拉斯，并努力与曾经建立起他们帝国的那股魔法能量的诱惑做斗争。";
S["RACE_INFO_DRAENEI"] = "        高贵的德莱尼人从他们生活着的阿古斯世界逃出来之后，被燃烧军团追杀了数不清的岁月，最终在一个遥远的星球定居。他们与这个世界的原住民——信奉萨满教义的兽人和平相处，并给这里起名为德拉诺。在兽人被燃烧军团腐蚀而变得嗜血好战之后，德莱尼人几乎遭到了灭顶之灾。一部分幸存者逃到了艾泽拉斯，并在这里找到了共同对抗燃烧军团的盟友。";
S["RACE_INFO_DRAENEI_FEMALE"] = "高贵的德莱尼人从他们生活着的阿古斯世界逃出来之后，被燃烧军团追杀了数不清的岁月，最终在一个遥远的星球定居。他们与这个世界的原住民——信奉萨满教义的兽人和平相处，并给这里起名为德拉诺。在兽人被燃烧军团腐蚀而变得嗜血好战之后，德莱尼人几乎遭到了灭顶之灾。一部分幸存者逃到了艾泽拉斯，并在这里找到了共同对抗燃烧军团的盟友。";
S["RACE_INFO_DWARF"] = "        很久以来，矮人只关心深埋在地底的财富。后来在一些被发掘出来的文献上记录着：某个神一般的种族创造了矮人，并赋予他们特殊的能力。为了对自己种族的起源有更多的了解，矮人们开始全力挖掘失落的神器，搜集远古的知识。今天，矮人的考古学家已经遍布了世界各地。";
S["RACE_INFO_DWARF_FEMALE"] = "很久以来，矮人只关心深埋在地底的财富。后来在一些被发掘出来的文献上记录着：某个神一般的种族创造了矮人，并赋予他们特殊的能力。为了对自己种族的起源有更多的了解，矮人们开始全力挖掘失落的神器，搜集远古的知识。今天，矮人的考古学家已经遍布了世界各地。";
S["RACE_INFO_GNOME"] = "        虽然生活在卡兹莫丹的侏儒身材都很矮小，但他们还是凭借超群的智慧在世界上扮演着举足轻重的角色。他们的地下王国诺莫瑞根一度被认为是蒸汽动力科技造就的奇迹。但是，由于石颚怪的大举入侵，这座城市最终还是陷落了。现在痛失家园的侏儒们在矮人的领地内四处流浪，尽可能地为他们的盟友提供援助。";
S["RACE_INFO_GNOME_FEMALE"] = "虽然生活在卡兹莫丹的侏儒身材都很矮小，但他们还是凭借超群的智慧在历史上占据了一席之地。他们的地下王国诺莫瑞根是蒸汽动力科技的奇迹，在工程学和奥术上的造诣也在历次战役中让联盟获益良多。";
S["RACE_INFO_GOBLIN"] = "科赞岛上的地精曾经是丛林巨魔的奴隶，被强迫开采深埋于卡亚罗山脉地底的卡亚矿石。然而不为人知的是，这些矿物具有某种神秘的魔法效力，受其影响的地精很快就变得既聪明又狡猾。醉心于工程学和炼金术，地精秘密地发明出了各式威力强大的神奇道具，并借此推翻了巨魔主人的统治，在科赞岛上建立了自己的家园。在那之后，地精大师级的商事手腕迅速崭露头角，他们的环球贸易寡头公司支配着整个艾泽拉斯世界的商业。";
S["RACE_INFO_HIGHMOUNTAINTAUREN"] = "至高岭的牛头人崇敬大地、河流与天空之灵。在过去的诸多时代中，他们一直都守护着自己的圣山，而如今，他们已经做好了准备，想要前往破碎群岛之外的世界冒险。";
S["RACE_INFO_HIGHMOUNTAINTAUREN_FEMALE"] = "至高岭的牛头人崇敬大地、河流与天空之灵。在过去的诸多时代中，他们一直都守护着自己的圣山，而如今，他们已经做好了准备，想要前往破碎群岛之外的世界冒险。";
S["RACE_INFO_HUMAN"] = "        人类是个年轻而多才多艺的种族。无论是在战斗技巧、制造技术还是操控魔法方面，人类都有着很高的造诣。勇猛和乐观的天性使人类建造了许多世界上最伟大的王国。在这个动乱的时代，经历了世代纷争的人类正在努力恢复昔日的辉煌，创造光明的未来。";
S["RACE_INFO_HUMAN_FEMALE"] = "人类是个年轻而多才多艺的种族，可以以惊人的效率学习战斗技巧、制造技术和操控魔法的技艺。靠着勇猛和乐观的天性，人类建造了许多世界上最伟大的王国。在这个动乱的时代，经历了世代纷争的人类正在努力恢复昔日的辉煌，创造光明的未来。";
S["RACE_INFO_LIGHTFORGEDDRAENEI"] = "这些德莱尼与燃烧军团进行了一场漫长而艰苦的战争。他们被灌注了圣光之力，成为了强力的武器。获得最终的胜利后，这些光铸者担负起了保卫艾泽拉斯的责任。";
S["RACE_INFO_LIGHTFORGEDDRAENEI_FEMALE"] = "这些德莱尼与燃烧军团进行了一场漫长而艰苦的战争。他们被灌注了圣光之力，成为了强力的武器。获得最终的胜利后，这些光铸者担负起了保卫艾泽拉斯的责任。";
S["RACE_INFO_NIGHTBORNE"] = "数千年间，苏拉玛的夜之子一直在奥术屏障下与世隔绝地生活。同时，在暗夜井的魔力影响下，他们的外形也逐渐改变了。这些骄傲而高贵的精灵如今想要找回他们在艾泽拉斯的位置。";
S["RACE_INFO_NIGHTBORNE_FEMALE"] = "数千年间，苏拉玛的夜之子一直在奥术屏障下与世隔绝地生活。同时，在暗夜井的魔力影响下，他们的外形也逐渐改变了。这些骄傲而高贵的精灵如今想要找回他们在艾泽拉斯的位置。";
S["RACE_INFO_NIGHTELF"] = "        一万年前，暗夜精灵就已经建立了一个庞大的帝国，但是他们无节制地滥用魔法，最终导致了帝国的毁灭。幸存的暗夜精灵怀着悲伤重新回到了森林中，过起了与世隔绝的隐居生活，直到他们过去的敌人燃烧军团重新来到这个世界。现在，别无选择的暗夜精灵重新开始和外界接触，为了自己的种族能在这个新的世界中生存下去而战斗着。";
S["RACE_INFO_NIGHTELF_FEMALE"] = "一万年前，暗夜精灵就已经建立了一个庞大的帝国，但是他们无节制地滥用魔法，最终导致了帝国的毁灭。幸存的暗夜精灵怀着悲伤重新回到了森林中，过起了与世隔绝的隐居生活，直到他们过去的敌人燃烧军团重新来到这个世界。现在，别无选择的暗夜精灵重新开始和外界接触，为了自己的种族能在这个新的世界中生存下去而战斗着。";
S["RACE_INFO_ORC"] = "        兽人原本居住在德拉诺世界，过着信仰萨满教的和平生活。后来兽人被燃烧军团奴役，与艾泽拉斯的人类进行了惨烈的战争。多年之后，兽人最终摆脱了恶魔的控制并重新获得了自由。今天，他们为了荣誉和尊严，与一切憎恨和羞辱他们的敌人作战。";
S["RACE_INFO_ORC_FEMALE"] = "兽人原本居住在德拉诺世界，过着信仰萨满教的和平生活。后来兽人被燃烧军团奴役，与艾泽拉斯的人类进行了惨烈的战争。多年之后，兽人最终摆脱了恶魔的控制并重新获得了自由。今天，他们为了荣誉和尊严，与一切憎恨和羞辱他们的敌人作战。";
S["RACE_INFO_SCOURGE"] = "        在摆脱了巫妖王的铁腕统治之后，由女妖之王希尔瓦娜斯领导的被遗忘者开始找寻新的自由，并渴望对巫妖王的天灾军团进行复仇。当然，想要从这个世界上彻底驱逐一切亡灵的人类也是他们不共戴天的敌人。被遗忘者对他们的盟友也毫不关心，因为对他们来说，加入部落只是为了让他们黑暗而邪恶的计划更进一步的阶梯。";
S["RACE_INFO_SCOURGE_FEMALE"] = "作为昔日的无脑奴隶，阴郁的被遗忘者推翻了可怕的巫妖王，转而向邪恶的女妖之王希尔瓦娜斯宣示效忠。在她的领导下，被遗忘者大军夺回了洛丹伦王国的废墟。然而面对一心复仇的人类，以及那些不信任亡灵邪恶动机的部落盟友，每一天对他们来说都是持续不断的抗争与战斗。";
S["RACE_INFO_TAUREN"] = "        牛头人一直以来都在为了自然的平衡而努力，并时刻遵循着他们所信仰的女神：大地母亲的意愿。在邪恶的半人马最近发动的一次突袭下，牛头人的种族险些被彻底灭亡，兽人及时伸出的援手让他们最终击败了入侵者。为了对兽人表示感谢，牛头人加入了部落，这近一步巩固了两个种族之间的友谊。";
S["RACE_INFO_TAUREN_FEMALE"] = "牛头人一直以来都在努力保护自然的平衡，并时刻遵循着他们所信仰的女神：大地母亲的意愿。众多游牧部族聚集在同一面大旗下，定居于莫高雷的肥沃平原上。要不是兽人及时伸出了援手，这个种族可能已经被劫掠成性的半人马灭绝了。牛头人至今依然牢记这笔血债，为保护自己的土地而与部落并肩作战。";
S["RACE_INFO_TROLL"] = "        暗矛部落的巨魔原本居住在荆棘谷的丛林中，但是由于不同种族之间的连年征战而被迫流离失所。最终这些巨魔与兽人成为了朋友，年轻的兽人酋长萨尔成功地说服了巨魔跟随他一起来到卡利姆多大陆。虽然巨魔继承了他们种族的黑暗本性，但是部落中的其他种族仍然对他们表示出了尊重和敬意。";
S["RACE_INFO_TROLL_FEMALE"] = "暗矛部落的巨魔原本居住在荆棘谷的丛林中，但是由于各阵营之间的连年征战而被迫流离失所。兽人的部落向他们伸出了援手，并说服暗矛部落渡过无尽之海，在卡利姆多的蛮荒之地定居下来。虽然他们继承了巨魔种族的黑暗本性，但是暗矛巨魔主张保持部落的团结，并愿意以强大的武力和原始部族魔法为部落共同的事业而效力。";
S["RACE_INFO_VOIDELF"] = "这些被驱逐的精灵试图掌握虚空的堕落魔力，但却意外地令自己的外形发生了改变。他们决心掌握这种新的力量，并抵抗企图引诱他们堕入疯狂的低语。";
S["RACE_INFO_VOIDELF_FEMALE"] = "这些被驱逐的精灵试图掌握虚空的堕落魔力，但却意外地令自己的外形发生了改变。他们决心掌握这种新的力量，并抵抗企图引诱他们堕入疯狂的低语。";
S["RACE_INFO_WORGEN"] = "在第三次战争期间，东部王国的大法师阿鲁高将狼人释放到了这个世界上。狼人最初被当作对抗亡灵天灾的武器，然而不久之后，这些野兽就变成了洛丹伦的人民难以承受的灾厄。某种神秘的诅咒开始传播，将那些与狼人一同作战的人类也变成了这种獠牙利爪的怪物。诅咒很快就蔓延到了吉尔尼斯王国，王国的居民被困在了那堵原本建来保护他们的高墙之后。现在，诅咒的幸存者正为他们的人民寻求新的命运，历史的宿命又翻开了一页......";
S["RACIAL_SKILLS"] = "%s技能：";
