S["TUTORIAL2"] = "你可以使用ASDW键或者方向键来控制角色的移动，同时按下鼠标左右键也可以控制移动。";
S["TUTORIAL20"] = "右键点击商人处的物品便可购买此物品，前提是你有足够的金钱。在打开商人货物界面的情况下点击自己背包中的某个物品可以将其出售给商人。";
S["TUTORIAL21"] = "你可以点击屏幕中央下部的金色杯子图标来打开任务日志，然后查看自己的任务。";
S["TUTORIAL22"] = "如果你和另外一个玩家相处得很愉快，就把这个玩家加入好友名单吧！点击社交按钮然后将其加入你的好友名单。";
S["TUTORIAL23"] = "你可以按回车键然后输入一条信息，你旁边的玩家都可以收到这条信息。";
S["TUTORIAL24"] = "要想给你的角色穿戴各种装备的话，你可以打开角色面板，然后把想要装备的物品从背包中拖到面板中。";
S["TUTORIAL25"] = "你现在处于鬼魂状态，可以通过回去找到自己的尸体或者和旁边的灵魂医者对话来复活。你的尸体的位置会在地图上标示出来，右上角的小地图上也会有箭头指向你的尸体所在的方向。";
S["TUTORIAL26"] = "你现在处于精力充沛状态，将在杀死怪物后获得一定的额外经验值奖励。";
S["TUTORIAL27"] = "如果你游到远离陆地的深水区，就会看到一个疲倦槽。当你的疲倦槽完全耗尽时，你就会溺水死亡。";
S["TUTORIAL28"] = "游泳与走路基本相同，但是你可以按住鼠标右键并移动鼠标，以此来改变游泳的方向。";
S["TUTORIAL29"] = "当你的角色潜入水中时，你会看到一个呼吸槽。呼吸槽一旦用光，你的角色就会开始溺水。";
S["TUTORIAL3"] = "你可以按住左键来调整视角，而按住右键可以让你的角色与视野保持同时旋转。";
S["TUTORIAL30"] = "你的头像周围的黄色闪光表示你正在休息中。在休息状态下度过一段时间或者退出游戏之后，你下次登录游戏时可以获得暂时性的奖励，通过杀死怪物所获得的经验值提高。你可以向任意一位旅店老板索要炉石，便于你快速返回旅店。";
S["TUTORIAL31"] = "你已经拥有了一块炉石，它可以将你从现在的位置传送回你最后登记的那个旅店里。你每小时只能使用一次炉石。";
S["TUTORIAL32"] = "你进入了PvP模式，在这种状态下你的头像旁会显示你所属阵营的标志，敌对阵营的玩家可以自由攻击你。";
S["TUTORIAL33"] = "你可以按下空格键来进行跳跃。跳跃可以帮助你越过小型的障碍物，以及快速从水中来到陆地上。";
S["TUTORIAL34"] = "你已经完成了第一个任务！要获取奖励的话，只需回到指派你去完成这个任务的NPC处就可以了。当你达到了完成某个任务的条件时，可以在微缩地图上看到该NPC的标记。";
S["TUTORIAL35"] = "你刚刚点击了一个飞行管理员，他/她是专门训练飞行兽并提供飞行运输服务的人。只需一小笔花费，你就可以飞往任何你曾经接触过的飞行管理员那里。当你发现一座新的城镇之后，最好先去找到该城镇的飞行管理员，以便日后能够快速抵达这里。";
S["TUTORIAL36"] = "你可以通过吃食物来加快生命值的回复速度，点击屏幕底部动作条中的食物图标就可以吃食物。但是在战斗中是不能吃食物的。";
S["TUTORIAL37"] = "你可以通过吃食物来加快生命值的回复速度，点击屏幕底部动作条中的食物图标就可以吃食物。但是在战斗中是不能吃食物的。";
S["TUTORIAL38"] = "你的角色可以学习最多两种专业，使你能够采集或制造珍贵的物品。你可以向各大主城中的守卫询问各种专业的训练师所在的位置。";
S["TUTORIAL39"] = "你可以邀请其他玩家与你组队，共同冒险和作战。组队使你可以轻松完成许多困难的任务，而且组队时还可以获得一定的经验值奖励。";
S["TUTORIAL4"] = "左键选择目标，右键进行相应的互动。";
S["TUTORIAL40"] = "你可以在人物出现地附近找到训练师来学习新的技能，当然他们不会全都站在你面前，所以你得要四处走动一下才能找到他们。";
S["TUTORIAL41"] = "你可以按Enter键然后输入一条信息。你旁边的玩家都能够收到这条信息。";
S["TUTORIAL42"] = "如果你碰到什么新的东西，在你屏幕底部将会出现一个帮助按钮。点击这个按钮来获取如何和这个世界相关内容进行交互的简单介绍。这些小提示从最基础的内容开始，然后慢慢会出现一些进阶内容。\n\n感谢你参加游戏，祝你在你的冒险旅程中好运！";
S["TUTORIAL43"] = "如果NPC头顶上标有灰色感叹号，则表示你的等级还无法接受他所给予的任务。当你升级之后再回来看看吧。";
S["TUTORIAL44"] = "你获得了一件远程武器。要使用它，请首先装备它，然后打开你的法术/技能书，将\"射击\"或\"投掷\"技能的图标拖拽到你的快捷栏中。";
S["TUTORIAL45"] = "你无法在不装备弹药的情况下使用弓和枪。你可以到城镇中的枪械或弓箭商人处购买弹药，然后右键点击弹药以装备它。";
S["TUTORIAL46"] = "你加入了一个团队（可以容纳最多40人的队伍）。\n\n|cffff2020当你在一个团队中时，就无法完成大多数非团队任务，比如杀死指定数量的怪物或收集指定数量的物品。|r";
S["TUTORIAL47"] = "你正在通过集合石等待加入一支小队。集合石指示器图标就在微缩地图的旁边。你可以点击该指示器将自己从集合石队列中移除。";
S["TUTORIAL48"] = "你正在等待进入战场的队列中。你可以将鼠标移至微缩地图旁的战场图标上以查看你的状态。";
S["TUTORIAL49"] = "你现在可以加入战场了。点击对话框中的\"加入战斗\"按钮或右键点击微缩地图上的战场图标以加入战场。";
S["TUTORIAL4_DWARF"] = "|cffffd200石腭入侵者|r就在附近。|cffffd200左键单击|r任意|cffffd200石腭入侵者|r以选定它。";
S["TUTORIAL4_GNOME"] = "|cffffd200癫狂的麻疯侏儒|r就在附近。|cffffd200左键单击|r任意|cffffd200癫狂的麻疯侏儒|r来选定它为目标。";
S["TUTORIAL4_NIGHTELF"] = "|cffffd200夜刃豹幼崽|r就在附近。|cffffd200左键单击|r任意|cffffd200夜刃豹幼崽|r来选定它为目标。";
S["TUTORIAL4_ORC"] = "|cffffd200杂斑野猪|r就在附近。|cffffd200左键单击|r任意|cffffd200杂斑野猪|r来选定它为目标。";
S["TUTORIAL4_SCOURGE"] = "|cffffd200无脑的僵尸|r就在附近。|cffffd200左键单击|r任意|cffffd200无脑的僵尸|r来选定它为目标。";
S["TUTORIAL4_TAUREN"] = "|cffffd200刺背入侵者|r就在附近。|cffffd200左键单击|r任意|cffffd200刺背入侵者|r来选定它为目标。";
S["TUTORIAL4_TROLL"] = "|cffffd200蒂基面具假人|r就在附近。|cffffd200左键单击|r任意|cffffd200蒂基面具假人|r来选定它为目标。";
S["TUTORIAL5"] = "右键点击目标移动到作战范围进入战斗模式";
S["TUTORIAL50"] = "钥匙链可以帮助你存放地下城的入口钥匙。钥匙链显示在你的动作条上的背包左边，它只能用来存放永久性的钥匙。";
S["TUTORIAL51"] = "因为你给你的帐号添加了安全令，您的背包增加了4格空间。";
S["TUTORIAL52"] = "恭喜！你获得了你的第一个战斗宠物。这个小家伙将会陪你走遍艾泽拉斯和其它世界的每个角落。|n|n你可以点击|cffffd200藏品|r按钮，在|cffffd200宠物手册|r中查看你所有的战斗宠物。";
S["TUTORIAL53"] = "恭喜，你已经学会了如何召唤你的第一头坐骑。这头强大的坐骑会载着你走遍艾泽拉斯以及更遥远的地方。|n|n你可以点击|cffffd200藏品|r按钮，在|cffffd200坐骑|r中查看自己所有的坐骑。你可以将最喜欢的坐骑的图标拖放到你的技能栏中，便于快速使用。";
S["TUTORIAL54"] = "你已经引起了一个具有敌意的怪物的注意。|n|n红色泛光表示怪物正在攻击你。黄色泛光表示你有受到攻击的危险。橙色泛光表示怪物正在攻击你，但有可能即将更换目标。";
S["TUTORIAL55"] = "恭喜！你已经击败了足够多的敌人，可以完成任务了|n|n去找任务给予者领取你的奖励吧。";
S["TUTORIAL55_DWARF"] = "恭喜！你已经消灭了足够的|cffffd200石腭入侵者|r以完成任务。|n|n回去找|cffffd200乔恩·铁枷|r领取奖励。";
S["TUTORIAL55_GNOME"] = "恭喜！你已经消灭了足够的|cffffd200癫狂的麻疯侏儒|r以完成任务。|n|n回去找|cffffd200内温·扭钳|r领取奖励。";
S["TUTORIAL55_HUMAN"] = "恭喜！你已经消灭了足够的|cffffd200黑石战狼|r以完成任务。|n|n回去找|cffffd200治安官玛克布莱德|r领取奖励。";
S["TUTORIAL55_NIGHTELF"] = "恭喜！你已经消灭了足够的|cffffd200夜刃豹幼崽|r以完成任务。|n|n回去找|cffffd200伊尔萨莱恩|r领取奖励。";
